<?php require __DIR__.'/../config/functions.php'; ensure_install(); require_member(); $out=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $r=call_agnes('video',array('model'=>'agnes-video-v2.0','prompt'=>$_POST['script'],'duration'=>$_POST['duration'],'resolution'=>$_POST['resolution'],'cost'=>5)); $out=$r['result']; get_db()->prepare('INSERT INTO generations(member_id,model_type,prompt,options,result_url,status,created_at) VALUES(?,?,?,?,?,"done",NOW())')->execute(array($_SESSION['member_id'],'video',$_POST['script'],json_encode(array('duration'=>$_POST['duration'],'resolution'=>$_POST['resolution']),JSON_UNESCAPED_UNICODE),$out)); } page_header('AI视频生成'); ?><form class="card" method="post"><h2>agnes-video-v2.0 视频生成</h2><input type="hidden" name="csrf" value="<?php echo csrf_token();?>"><textarea name="script" placeholder="视频脚本"></textarea><select name="duration"><option>5秒</option><option>10秒</option><option>30秒</option></select><select name="resolution"><option>720p</option><option>1080p</option></select><button>提交生成</button></form><div class="card"><progress value="100" max="100"></progress><p><?php echo esc($out); ?></p><?php if(filter_var($out,FILTER_VALIDATE_URL)) echo '<video src="'.esc($out).'" controls style="max-width:100%"></video><p><a href="'.esc($out).'" download>下载</a></p>'; ?></div><?php page_footer(); ?>
